def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    sigma = 0.2
    scores = np.exp(-(remaining ** 2) / (2 * (sigma ** 2)))
    return np.where(remaining < 0, -np.inf, scores)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    sigma1, target1 = 0.15, 0.2
    sigma2, target2 = 0.20, 0.8
    scores = 0.6 * np.exp(-((remaining - target1) ** 2) / (2 * sigma1 ** 2)) + 0.4 * np.exp(-((remaining - target2) ** 2) / (2 * sigma2 ** 2))
    return np.where(remaining < 0, -np.inf, scores)

